#!/usr/bin/env bash
# Renders the vLLM Semantic Router chart into the plain Kubernetes objects the CLI
# embeds (darkplum/k8s/semantic-router/rendered.yaml), so an operator needs no helm
# and no chart download. helm runs here, in CI and on a maintainer's machine, never
# on a customer's.
#
#   render-semantic-router.sh           write the rendered file
#   render-semantic-router.sh --check   fail if the committed file is not what this renders
#
# The chart version is pinned below and must equal semrouter.ChartVersion (a Go
# test compares them). The image is pinned by digest in values.yaml.
set -euo pipefail

CHART=oci://ghcr.io/vllm-project/charts/semantic-router
VERSION=0.3.0
NAMESPACE=darkplum-system

root="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
dir="$root/darkplum/k8s/semantic-router"
out="$dir/rendered.yaml"

command -v helm >/dev/null || { echo "helm is required to render the semantic router (it is preinstalled on GitHub-hosted runners)"; exit 1; }
case "$(helm version --template '{{.Version}}')" in
  v3.*) ;;
  *) echo "helm 3 is required"; exit 1 ;;
esac

render() {
  echo "# GENERATED by .github/scripts/render-semantic-router.sh from ${CHART##*/} ${VERSION} and values.yaml. Do not edit."
  echo "# Regenerate after changing values.yaml or the chart version; CI fails when this file is stale."
  helm template semantic-router "$CHART" --version "$VERSION" --namespace "$NAMESPACE" -f "$dir/values.yaml"
}

tmp="$(mktemp)"
trap 'rm -f "$tmp"' EXIT
render > "$tmp"
grep -q '@sha256:[0-9a-f]\{64\}' "$tmp" || { echo "the rendered router image is not pinned by digest"; exit 1; }

if [ "${1:-}" = "--check" ]; then
  if ! diff -u "$out" "$tmp"; then
    echo
    echo "darkplum/k8s/semantic-router/rendered.yaml is stale. Run .github/scripts/render-semantic-router.sh and commit the result."
    exit 1
  fi
  echo "rendered.yaml is current"
else
  cp "$tmp" "$out"
  echo "wrote $out"
fi
